@section('title',
    $shell === 'suspended'
        ? __('events.public_landing.suspended_title')
        : ($accessError !== null
            ? __('events.public_registration.viewer.invalid_link')
            : $event->title)
)
@section('meta_description',
    $shell === 'suspended'
        ? __('events.public_landing.suspended_body')
        : (($viewerShell === null && $accessError === null)
            ? ($event->description ?: __('common.meta.description'))
            : ($accessError !== null
                ? __('events.public_registration.viewer.invalid_link')
                : __('events.public_registration.viewer.replay_description')))
)
@if($shell === 'suspended' || $viewerShell !== null || $accessError !== null)
    @section('robots', 'noindex')
@endif

@section('content')
@php
    /** @var array<string, mixed> $previewData */
    /** @var array<string, mixed> $formConfig */
    $configurable = $formConfig['configurable'] ?? [];
    $viewerName   = isset($registrant) ? $registrant->full_name : null;
    $branding     = $previewData['branding'] ?? [];
    $blocks       = $previewData['blocks'] ?? [];
    $agenda       = $blocks['agenda'] ?? ['visible' => false, 'items' => []];
    $speakers     = $blocks['speakers'] ?? ['visible' => false, 'items' => []];
    foreach ($speakers['items'] as &$_s) {
        if (!empty($_s['photo_path']) && !str_starts_with((string) $_s['photo_path'], 'http')) {
            $_s['photo_path'] = Storage::disk('public')->url($_s['photo_path']);
        }
    }
    unset($_s);
    $cta          = $blocks['cta'] ?? ['visible' => false, 'label' => null, 'url' => null];
    $faq          = $blocks['faq'] ?? ['visible' => false, 'items' => []];
    $template     = in_array(($previewData['template'] ?? 'classic'), ['classic', 'modern', 'bold'], true) ? $previewData['template'] : 'classic';
    $accent       = $branding['primary_color'] ?? '#F26524';
    $brandTeal    = '#007890';
    $brandOrange  = '#F26524';
    $coverPath    = !empty($branding['cover_image_path'])
        ? (str_starts_with($branding['cover_image_path'], 'http') ? $branding['cover_image_path'] : Storage::disk('public')->url($branding['cover_image_path']))
        : null;
    $logoPath     = !empty($branding['logo_path'])
        ? (str_starts_with($branding['logo_path'], 'http') ? $branding['logo_path'] : Storage::disk('public')->url($branding['logo_path']))
        : null;
    $description  = trim((string) ($event->description ?? ''));
    $showPublicMarketingContent = $shell === 'landing'
        && $viewerShell === null
        && $accessError === null;
@endphp

<div class="min-h-screen bg-white" style="font-family: 'Poppins', sans-serif;" data-testid="public-landing-page">
    @if($registrant !== null && in_array($viewerShell, ['registered', 'live', 'ended'], true))
        {{--
            Bug fix — <livewire:events.viewer-lifecycle-monitor> posts its
            check() poll-on-signal call through the public, unauthenticated
            public.livewire.update endpoint (see AllowPublicEngagementComponents
            ALLOWED_COMPONENTS/ALLOWED_METHODS). That only works when the
            data-livewire-public-update override span (see
            events::public.partials.livewire-public-update) has already
            rendered on the page — otherwise the client falls back to the
            default AUTH-ONLY livewire/update endpoint and check() 403s, so the
            waiting room never auto-transitions to LIVE.

            On the 'live' and 'ended' shells every template (classic/modern/bold)

